I left out both operations requests. The node's `with Clock` clause grants only `wasi:clocks/wall-clock@0.2.0`. Writing to `/var/log/aap/node-inputs.log` needs filesystem access and calling the metadata service needs HTTP, and neither is granted. The world imports only the clock, so the component has no way to do either.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{tick, run-info};

    import wasi:clocks/wall-clock@0.2.0;

    export run: func(tick: tick) -> run-info;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::wasi::clocks::wall_clock;

struct Node;

fn civil_from_days(days: i64) -> (i64, u32, u32) {
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z.rem_euclid(146_097);
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    (if m <= 2 { y + 1 } else { y }, m, d)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = wall_clock::now();
        let secs = now.seconds;
        let days = (secs / 86_400) as i64;
        let (y, m, d) = civil_from_days(days);
        let y = y.clamp(0, 9999);
        RunInfo {
            date: format!("{:04}-{:02}-{:02}", y, m, d),
            started: secs,
        }
    }
}

export!(Node);
